input.script:
services = boundary retry 2 { return list_services({}) } catch err { return fail("LIST_FAILED", err.message) }
counts = for svc in services {
    res = boundary retry 2 { return search_logs({ service: svc, level: "ERROR", page: 1 }) } catch err {
        return fail("LOGS_FAILED", svc + ": " + err.message)
    }
    return { service: svc, total_errors: res.total_items, total_pages: res.total_pages }
}
return counts

p1 = boundary retry 2 { return search_logs({ service: "payments", level: "ERROR", page: 1 }) } catch err { return fail("L1", err.message) }
p2 = boundary retry 2 { return search_logs({ service: "payments", level: "ERROR", page: 2 }) } catch err { return fail("L2", err.message) }
deploys = boundary retry 2 { return get_deploys({ service: "payments" }) } catch err { return fail("DEP", err.message) }
owner = boundary retry 2 { return get_service_owners({ service: "payments" }) } catch err { return fail("OWN", err.message) }
logs = p1.items + p2.items
return { logs: logs, deploys: deploys, owner: owner }
